def __transform_results_json(results_obj):
    elections = results_obj["elections"]
    all_districts_obj = elections[0]["districts"]
    elections_model = Elections()
    elections_model.all_candidates = __transform_all_candidates_json(all_districts_obj)
    elections_model.all_parties = __transform_parties_json(results_obj["parties"]["2024"])
    elections_model.all_departments = __transform_departments_json(results_obj["departments"])
    year = elections[0]["year"]
    elections_results = {year : elections_model}
    return elections_results

def __transform_all_candidates_json(districts_obj):
    candidates_districts = []
    for district_obj in districts_obj : 
        district = District()
        district.code = district_obj["number"]
        district.department_code = district_obj["department code"]
        district.name = district_obj["label"]
        all_candidates_in_this_district = __transform_candidate_json(district_obj["candidates"], district)
        candidates_districts.append(all_candidates_in_this_district)
    return candidates_districts

def __transform_candidate_json(candidates_obj, district):
    candidates = []
    for candidate_obj in candidates_obj:
        candidate_person = CongressPerson()
        candidate_person.district = district
        candidate_person.first_name  = candidate_obj["firstName"]
        candidate_person.last_name = candidate_obj["lastName"]
        candidate_person.parti_code = candidate_obj["partiCode"]
        candidate_person.sexe = candidate_obj["sexe"]
        candidate_person.vote = candidate_obj["vote"]
        candidate_person.vote_percentage = candidate_obj["voteByExpressed"]
        candidates.append(candidate_person)
    return candidates

def __transform_parties_json(parties_obj):
    parties = []
    for party_obj in parties_obj: 
        party = Party()
        party.name = party_obj["name"]
        party.code = party_obj["code"]
        party.family = party_obj["family"]
        parties.append(party)
    return parties

def __transform_departments_json(departments_obj):
    departments = []
    for department_obj in departments_obj: 
        department = Department()
        department.code = department_obj["code"]
        department.name = department_obj["name"]
        departments.append(department)
    return departments